const t={maxFlow:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Знайдіть найбільший об'ємний потік (mm³/s), який ваш хотенд може стабільно тримати - поступово підвищуючи потік і стежачи за навантаженням StallGuard екструдера, доки шестерня не почне прослизати. Спершу перегляньте план; живий тест нагріває та екструдує, тому підготуйте принтер перед запуском."}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Довідка"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Про Max-Flow"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Закрити"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"Як користуватися"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"Задайте температуру тесту та діаметр філаменту (виберіть хотенд, щоб заповнити автоматично)."}},{t:0,b:{t:2,i:[{t:3}],s:"Перегляньте план - він показує кожен крок потоку та скільки філаменту виштовхується."}},{t:0,b:{t:2,i:[{t:3}],s:"Позначте чек-лист безпеки, потім запустіть живий тест (нагрів + екструзія)."}},{t:0,b:{t:2,i:[{t:3}],s:"Прочитайте максимальний стабільний потік і скопіюйте рекомендоване значення для слайсера."}}],topics:{howItWorks:{title:{t:0,b:{t:2,i:[{t:3}],s:"Як працює тест"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Екструдер подає філамент з поступово зростаючим об'ємним потоком. Поки рифлена шестерня тримає чисто, показник навантаження StallGuard залишається стабільним; щойно починається прослизання, показники починають стрибати. Найбільший потік, досягнутий до цього стрибка, і є вашим стабільним максимальним потоком. Підвищення зупиняється одразу, щойно виявлено прослизання, тому жоден філамент не стирається після першого прослизання."}}},stallguard:{title:{t:0,b:{t:2,i:[{t:3}],s:"Виявлення прослизання StallGuard"}},body:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard - це функція драйвера TMC, яка повідомляє навантаження двигуна. Цей тест відбирає його багато разів на кожен крок потоку та шукає різке зростання розкиду (IQR) або варіації (CV) - ознаку того, що шестерня втрачає зчеплення. Порогові значення беруться з профілю для кожного драйвера. Зверніть увагу: на екструдері з TMC2209 це використовує експериментальний шлях SG4, тому ставтеся до першого запуску як до калібрування."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Безпека"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Це гарячий, рухомий тест, який навмисно змушує екструдер прослизати. Завантажте філамент, переконайтеся, що сопло вільне (над столом або зоною відходів), і будьте поруч. Запуск відхиляється під час друку, а нагрівач завжди вимикається після завершення."}}},slicer:{title:{t:0,b:{t:2,i:[{t:3}],s:"Використання результату"}},body:{t:0,b:{t:2,i:[{t:3}],s:`Внесіть рекомендоване значення у параметр "максимальна об'ємна швидкість" вашого слайсера (для кожного філаменту). Консервативне значення (80% від виміряного максимуму) - безпечна щоденна межа; збалансоване значення (90%) дещо агресивніше. Вищі температури хотенда зазвичай підвищують досяжний потік.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Глосарій"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{flow:{term:{t:0,b:{t:2,i:[{t:3}],s:"Об'ємний потік"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Скільки пластику хотенд розплавляє за секунду (mm³/s) - реальна межа швидкості для швидкого друку."}}},stallguard:{term:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Сигнал драйвера TMC, що повідомляє механічне навантаження двигуна, тут використовується для виявлення прослизання екструдера."}}},slip:{term:{t:0,b:{t:2,i:[{t:3}],s:"Прослизання"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Коли шестерня екструдера більше не може досить швидко тримати філамент і прослизає - стеля потоку."}}},meltzone:{term:{t:0,b:{t:2,i:[{t:3}],s:"Зона плавлення"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Нагріта довжина хотенда; довша зона плавлення (напр. Volcano) підтримує вищий потік."}}}}},params:{title:{t:0,b:{t:2,i:[{t:3}],s:"Параметри тесту"}},temperature:{t:0,b:{t:2,i:[{t:3}],s:"Температура (°C)"}},filamentDiameter:{t:0,b:{t:2,i:[{t:3}],s:"Ø філаменту (mm)"}},hotend:{t:0,b:{t:2,i:[{t:3}],s:"Хотенд (необов'язково)"}},hotendNone:{t:0,b:{t:2,i:[{t:3}],s:"- немає -"}},hotendHint:{t:0,b:{t:2,i:[{t:3,v:"Очікувано ~"},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},startFlow:{t:0,b:{t:2,i:[{t:3}],s:"Початковий потік (mm³/s)"}},endFlow:{t:0,b:{t:2,i:[{t:3}],s:"Кінцевий потік (mm³/s)"}},stepFlow:{t:0,b:{t:2,i:[{t:3}],s:"Крок (mm³/s)"}},samples:{t:0,b:{t:2,i:[{t:3}],s:"Зразків / крок"}},extrudePerStep:{t:0,b:{t:2,i:[{t:3}],s:"Екструзія / крок (mm)"}},driver:{t:0,b:{t:2,i:[{t:3}],s:"Драйвер екструдера"}},driverDetected:{t:0,b:{t:2,i:[{t:3}],s:"виявлено з принтера"}},autoStealthchop:{t:0,b:{t:2,i:[{t:3}],s:"Авто-увімкнення StealthChop для тесту"}},autoStealthchopHint:{t:0,b:{t:2,i:[{t:3}],s:"Лише TMC2209/2240: тимчасово записує stealthchop_threshold для екструдера, щоб StallGuard міг читати, потім коментує його після тесту. Відновлює printer.cfg; перезапуск прошивки в обидва боки."}},method:{t:0,b:{t:2,i:[{t:3}],s:"Метод виявлення"}},methodHint:{t:0,b:{t:2,i:[{t:3}],s:"Auto використовує StallGuard з переходом на акселерометр інструментальної голівки (вібрація), коли StallGuard не може читати. Метод акселерометра експериментальний."}}},method:{auto:{t:0,b:{t:2,i:[{t:3}],s:"Auto"}},stallguard:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},accel:{t:0,b:{t:2,i:[{t:3}],s:"Акселерометр"}}},plan:{button:{t:0,b:{t:2,i:[{t:3}],s:"Переглянути план"}},title:{t:0,b:{t:2,i:[{t:3}],s:"Заплановане підвищення"}},stepCount:{t:0,b:{t:2,i:[{t:4,k:"count"},{t:3,v:" кроків"}]}},totalExtrude:{t:0,b:{t:2,i:[{t:4,k:"mm"},{t:3,v:" mm філаменту"}]}},sgField:{t:0,b:{t:2,i:[{t:3,v:"Поле StallGuard: "},{t:4,k:"field"}]}},sgFieldUnknown:{t:0,b:{t:2,i:[{t:3}],s:"Для цього драйвера невідоме поле StallGuard"}},flowHead:{t:0,b:{t:2,i:[{t:3}],s:"Потік (mm³/s)"}},feedrateHead:{t:0,b:{t:2,i:[{t:3}],s:"Подача (mm/min)"}},warning:{t:0,b:{t:2,i:[{t:3}],s:"Живий тест нагріває хотенд та екструдує філамент, навмисно до точки прослизання. Лише перегляд - поки нічого не запускається."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Перед запуском - чек-лист безпеки"}},items:[{t:0,b:{t:2,i:[{t:3}],s:"Філамент завантажено і він подається вільно."}},{t:0,b:{t:2,i:[{t:3}],s:"Сопло вільне - над столом або смітником для відходів, не у повітрі над деталями."}},{t:0,b:{t:2,i:[{t:3}],s:"Я погоджуюсь, що це навмисно зітре/прослизне частину філаменту."}},{t:0,b:{t:2,i:[{t:3}],s:"Я залишатимуся біля принтера протягом усього тесту."}}],ack:{t:0,b:{t:2,i:[{t:3}],s:"Я зробив усе вищезазначене, і принтер готовий"}},note:{t:0,b:{t:2,i:[{t:3}],s:"Запуск відхиляється під час друку; нагрівач автоматично вимикається наприкінці."}}},run:{button:{t:0,b:{t:2,i:[{t:3}],s:"Запустити живий тест"}},running:{t:0,b:{t:2,i:[{t:3}],s:"Виконується… (нагрів + екструзія)"}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:"Почати живий тест max-flow?"}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:"Це нагріває хотенд до "},{t:4,k:"temp"},{t:3,v:" °C і екструдує до "},{t:4,k:"mm"},{t:3,v:" mm філаменту, підвищуючи потік, доки екструдер не прослизне."}]}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Запустити зараз"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Скасувати"}},busy:{t:0,b:{t:2,i:[{t:3}],s:"Відхилено: принтер зайнятий (друкує або на паузі). Спробуйте знову, коли він буде вільний."}},error:{t:0,b:{t:2,i:[{t:3}],s:"Тест не вдався."}},noSg:{t:0,b:{t:2,i:[{t:3}],s:"Не прочитано жодного зразка StallGuard - результат прослизання може бути ненадійним. Імовірно, потрібно налаштувати живе поле SG драйвера для цієї моделі."}},progress:{t:0,b:{t:2,i:[{t:3,v:"Крок "},{t:4,k:"step"},{t:3,v:"/"},{t:4,k:"total"},{t:3,v:" - "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},starting:{t:0,b:{t:2,i:[{t:3}],s:"Нагрів / запуск…"}},abort:{t:0,b:{t:2,i:[{t:3}],s:"Перервати запуск"}},cancelling:{t:0,b:{t:2,i:[{t:3}],s:"Переривання…"}},cancelled:{t:0,b:{t:2,i:[{t:3}],s:"Запуск перервано - нагрівач вимкнено."}},reattached:{t:0,b:{t:2,i:[{t:3}],s:"Знову під'єднано: цей результат завершився, поки сторінка була неактивна."}},failed:{t:0,b:{t:2,i:[{t:3}],s:"Запуск max-flow не вдався."}},abortNote:{t:0,b:{t:2,i:[{t:3}],s:"Переривання завжди вимикає нагрівач."}},parkNote:{t:0,b:{t:2,i:[{t:3}],s:"Перед нагрівом принтер виконує домашнє позиціонування (за потреби) і центрує сопло для чіткого огляду."}},phase:{enabling:{t:0,b:{t:2,i:[{t:3}],s:"Увімкнення StealthChop…"}},homing:{t:0,b:{t:2,i:[{t:3}],s:"Домашнє позиціонування принтера…"}},centering:{t:0,b:{t:2,i:[{t:3}],s:"Центрування сопла…"}},heating:{t:0,b:{t:2,i:[{t:3}],s:"Нагрів хотенда…"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"Перевірка сигналу StallGuard…"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"Підвищення потоку…"}},reverting:{t:0,b:{t:2,i:[{t:3}],s:"Відновлення конфігурації…"}}},step:{home:{t:0,b:{t:2,i:[{t:3}],s:"Дім"}},center:{t:0,b:{t:2,i:[{t:3}],s:"Центр"}},heat:{t:0,b:{t:2,i:[{t:3}],s:"Нагрів"}},check:{t:0,b:{t:2,i:[{t:3}],s:"Перевірка"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"Підвищення"}}}},camera:{title:{t:0,b:{t:2,i:[{t:3}],s:"Жива камера"}},live:{t:0,b:{t:2,i:[{t:3}],s:"LIVE"}},error:{t:0,b:{t:2,i:[{t:3}],s:"Камера недоступна."}},willShow:{t:0,b:{t:2,i:[{t:3}],s:"Жива камера показуватиме сопло під час тесту."}},minimize:{t:0,b:{t:2,i:[{t:3}],s:"Згорнути"}},maximize:{t:0,b:{t:2,i:[{t:3}],s:"Розгорнути"}},enlarge:{t:0,b:{t:2,i:[{t:3}],s:"Збільшити"}},shrink:{t:0,b:{t:2,i:[{t:3}],s:"Зменшити"}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:"Результат"}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:"Макс. стабільний потік"}},slipAt:{t:0,b:{t:2,i:[{t:3,v:"Прослизання виявлено на "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},noSlip:{t:0,b:{t:2,i:[{t:3}],s:"Прослизання не виявлено аж до найвищого протестованого потоку"}},reason:{t:0,b:{t:2,i:[{t:3}],s:"Деталі"}},recommendTitle:{t:0,b:{t:2,i:[{t:3}],s:"Рекомендовані значення для слайсера (максимальна об'ємна швидкість)"}},conservative:{t:0,b:{t:2,i:[{t:3}],s:"Консервативне (80%)"}},balanced:{t:0,b:{t:2,i:[{t:3}],s:"Збалансоване (90%)"}},units:{t:0,b:{t:2,i:[{t:3}],s:"mm³/s"}},fromBefore:{t:0,b:{t:2,i:[{t:3,v:"Виміряно раніше ("},{t:4,k:"at"},{t:3,v:") - запустіть знову для свіжих значень."}]}},unreliableTitle:{t:0,b:{t:2,i:[{t:3}],s:"Ненадійно - немає сигналу StallGuard"}},unmeasured:{t:0,b:{t:2,i:[{t:3}],s:"досягнуто, не підтверджено"}},via:{t:0,b:{t:2,i:[{t:3,v:"Виміряно через "},{t:4,k:"method"}]}},accelExperimental:{t:0,b:{t:2,i:[{t:3}],s:"Виміряно за вібрацією (акселерометр) - експериментально; сприймайте число як орієнтир, а не точну стелю."}}},states:{loadingHotends:{t:0,b:{t:2,i:[{t:3}],s:"Завантаження хотендів…"}}}}};export{t as default};
